export interface Message {
  id: string
  senderId: string
  text: string
  sentAt: string
  /** Simulated automatic reply generated by the demo (not typed by a person). */
  automated?: boolean
}

export interface Conversation {
  id: string
  listingId: string
  buyerId: string
  sellerId: string
  messages: Message[]
  updatedAt: string
  /** When each participant last opened the conversation (for unread indicators). */
  lastReadAt: Record<string, string>
}
